# `active_test=False` : voir l'en-tete. Sans lui, un produit archive est
# invisible et l'on en cree un doublon.
Categorie = env["product.category"].sudo()
Produit = env["product.product"].sudo().with_context(active_test=False)


def get_or_create_category(name, parent=None):
    domaine = [("name", "=", name), ("parent_id", "=", parent.id if parent else False)]
    rec = Categorie.search(domaine, limit=1)
    if rec:
        return rec
    vals = {"name": name}
    if parent:
        vals["parent_id"] = parent.id
    return Categorie.create(vals)


racine = get_or_create_category("JULABA")
categories = {}
for item in CATALOGUE:
    fam = item["family"]
    sub = item["subfamily"]
    if fam not in categories:
        categories[fam] = get_or_create_category(fam, racine)
    key = (fam, sub)
    if key not in categories:
        categories[key] = get_or_create_category(sub, categories[fam])

crees = 0
maj = 0
reactives = 0
for item in CATALOGUE:
    ref = item["ref"]
    vals = {
        "name": item["name"],
        "categ_id": categories[(item["family"], item["subfamily"])].id,
        # Odoo 19 : `type='consu'` designe un bien materiel, et c'est
        # `is_storable` qui le rend suivi en stock — donc qui le fait entrer
        # au catalogue JULABA (voir backend/src/odoo-gateway/produit-mapper.ts,
        # `estArticleCatalogue`).
        "type": "consu",
        "is_storable": True,
        "sale_ok": True,
        "purchase_ok": True,
        "active": True,
        # Prix volontairement nuls — le referentiel ne porte pas de prix.
        "list_price": 0.0,
        "standard_price": 0.0,
    }
    rec = Produit.search([("default_code", "=", ref)], limit=1)
    if rec:
        if not rec.active:
            reactives += 1
        rec.write(vals)
        maj += 1
    else:
        Produit.create({**vals, "default_code": ref})
        crees += 1

# `odoo shell` fait un rollback apres execution du script (odoo/cli/shell.py) :
# sans ce commit explicite, tout ce qui precede serait perdu.
env.cr.commit()

print(f"[catalogue-maitre] termine — {len(CATALOGUE)} references, {crees} creees, {maj} mises a jour, {reactives} reactivee(s)")
print("[catalogue-maitre] prix=0, aucun stock touche, is_storable=true")
print(f"CATALOGUE_MAITRE_REFERENCES={len(CATALOGUE)}")
print(f"CATALOGUE_MAITRE_CREEES={crees}")
print(f"CATALOGUE_MAITRE_MAJ={maj}")
